package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.UrlVO;

class UrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of url of observed probe")
  void test_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    UrlValueHolder<Object> value = new UrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.url("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getUrl().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of url of observed probe")
  void test_url_value_holder_assign_value_object() {
    Object holder = new Object();
    UrlValueHolder<Object> value = new UrlValueHolder<>(holder);
    UrlVO vo = UrlVO.from("one");
    Assertions.assertFalse(value.getUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.url(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.url(Optional.empty()));
    Assertions.assertFalse(value.getUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.url(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of url of observed probe against the original")
  void test_url_value_holder_read() {
    Object holder = new Object();
    UrlValueHolder<Object> value = new UrlValueHolder<>(holder);
    UrlVO vo = UrlVO.from("one");
    UrlVO other = UrlVO.from("one");
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUrl(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.url(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of url of observed probe")
  void test_url_value_holder_unset() {
    Object holder = new Object();
    UrlValueHolder<Object> value = new UrlValueHolder<>(holder);
    UrlVO vo = UrlVO.from("one");
    value.url(vo);
    Assertions.assertSame(holder, value.unsetUrlIfMatches("url_other"));
    Assertions.assertTrue(value.getUrlValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUrlIfMatches("url"));
    Assertions.assertFalse(value.getUrlValue().isPresent(), "The field name must clear the value");
    value.url(vo);
    Assertions.assertSame(holder, value.unsetUrl());
    Assertions.assertFalse(value.getUrlValue().isPresent(), "Unset must clear the value");
  }
}
